def solve(text, required):
    if not required:
        return 0
    if not text:
        return -1
    required_set = set(required)
    for i in range(len(text)):
        for j in range(i, len(text)):
            if set(text[i:j+1]) >= required_set:
                return j-i+1
    return -1
```

