def solve(graph, start, end):
    if start == end:
        return 0
    visited = set()
    queue = [start]
    visited.add(start)
    while queue:
        node = queue.pop(0)
        for neighbor in graph.get(node, []):
            if neighbor == end:
                return 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return -1
```

