def solve(items):
    if not items:
        return 0
    max_len = 0
    for i in range(len(items)):
        seen = set()
        for j in range(i, len(items)):
            if items[j] in seen:
                break
            seen.add(items[j])
            max_len = max(max_len, j-i+1)
    return max_len
